<?php
 namespace Pterodactyl\Services\Dezerx\Ai; use Illuminate\Support\Str; use Illuminate\Http\Client\Response; use Illuminate\Support\Facades\Http; use Illuminate\Http\Client\ConnectionException; final class ModelHttp { private const RETRY_STATUSES = [408, 425, 429, 500, 502, 503, 504, 520, 521, 522, 524, 529]; private const BACKOFF = [2, 5, 10]; private const MAX_RETRY_AFTER = 20; public static function post(string $url, array $headers, array $body, ToolBox $tools, ?string $bearer = null): Response { $attempt = 0; while (true) { $tools->checkStop(); $timeout = (int) max(30, min(300, $tools->secondsLeft() + 60)); try { $request = Http::withHeaders($headers) ->acceptJson() ->connectTimeout(10) ->timeout($timeout) ->withOptions(['progress' => static function () use ($tools) { $tools->tick(); }]); if ($bearer !== null) { $request = $request->withToken($bearer); } $response = $request->post($url, $body); } catch (ConnectionException $exception) { if ($attempt < count(self::BACKOFF) && $tools->secondsLeft() > self::BACKOFF[$attempt] + 10) { $tools->pause(self::BACKOFF[$attempt++]); continue; } throw new AiUnavailable('The model could not be reached from this panel: ' . Str::limit($exception->getMessage(), 160)); } $tools->checkStop(); if (!in_array($response->status(), self::RETRY_STATUSES, true) || $attempt >= count(self::BACKOFF)) { return $response; } $wait = self::retryAfter($response) ?? self::BACKOFF[$attempt]; if ($wait > self::MAX_RETRY_AFTER || $tools->secondsLeft() < $wait + 10) { return $response; } $attempt++; $tools->pause($wait); } } public static function fail(Response $response, string $model): never { $status = $response->status(); $reason = self::reason($response); throw new AiUnavailable(match (true) { $status === 401 => 'The model service refused that API key (401): ' . $reason, $status === 403 => 'The model service refused this key (403): ' . $reason . (str_contains(strtolower($reason), 'denied access') ? ' This is the service blocking the account or project the key belongs to; a key from another project or account is needed.' : ''), $status === 404 || self::modelMissing($reason) => "The model \"{$model}\" is not available from this service ({$status}): {$reason} Choose another model in the assistant settings.", $status === 429 => 'The model is rate limited or out of quota right now: ' . $reason, $status >= 500 => 'The model service is having trouble (' . $status . '): ' . $reason, default => 'The model refused that request (' . $status . '): ' . $reason, }); } public static function reason(Response $response): string { $json = $response->json(); if (is_array($json) && array_is_list($json) && is_array($json[0] ?? null)) { $json = $json[0]; } $reason = null; if (is_array($json)) { $error = $json['error'] ?? null; $reason = match (true) { is_array($error) && is_string($error['message'] ?? null) => $error['message'], is_string($error) => $error, is_string($json['message'] ?? null) => $json['message'], is_string($json['detail'] ?? null) => $json['detail'], default => null, }; if (is_array($error) && is_array($error['metadata'] ?? null) && is_string($error['metadata']['raw'] ?? null)) { $reason .= ' (' . Str::limit($error['metadata']['raw'], 200) . ')'; } } $reason ??= trim(strip_tags($response->body())); $reason = preg_replace('/\s+/', ' ', $reason) ?? $reason; $reason = preg_replace('/\b(sk-ant-|sk-or-|sk-proj-|sk-|xai-|gsk_|AIza|pk-|rk-)[\w\-*.]{4,}/', '[key]', $reason) ?? $reason; return $reason === '' ? 'no reason given.' : Str::limit($reason, 400); } public static function replacement(Response $response): ?string { if ($response->status() !== 404 && !self::modelMissing(self::reason($response))) { return null; } if (preg_match('#\b(?:use|try|switch to|migrate to)\s+(?:the\s+)?(?:model\s+)?[`"\']?(?:models/)?([a-z0-9][a-z0-9.\-_]{2,60})#i', self::reason($response), $match) !== 1) { return null; } $model = rtrim($match[1], '.'); return str_contains($model, '-') && preg_match('/\d|latest/', $model) === 1 ? $model : null; } public static function contextTooLong(Response $response): bool { if ($response->status() !== 400 && $response->status() !== 413) { return false; } return preg_match('/context (length|window)|too many tokens|maximum.{0,40}tokens|prompt is too long|reduce the length|input is too long|request too large/i', self::reason($response)) === 1; } private static function modelMissing(string $reason): bool { return preg_match('/model.{0,80}(not found|does not exist|no longer available|not supported|decommissioned|deprecated|is not a valid model|unknown model)|no such model|invalid model/i', $reason) === 1; } private static function retryAfter(Response $response): ?int { $header = trim($response->header('Retry-After')); if ($header === '') { return null; } if (is_numeric($header)) { return max(1, (int) ceil((float) $header)); } $at = strtotime($header); return $at === false ? null : max(1, $at - time()); } } 